const emojiOptions=[['📚','Livros'],['🔬','Microscópio'],['🧬','Genética'],['🧪','Laboratório'],['🩺','Saúde'],['📝','Anotações'],['🎓','Faculdade'],['📌','Lembrete'],['📅','Agenda'],['⏰','Horário'],['🧹','Limpeza'],['🧽','Esponja'],['🚿','Banheiro'],['🍳','Cozinha'],['🛋️','Sala'],['🧺','Lavanderia'],['🏠','Casa'],['🌷','Flor'],['💗','Coração'],['☕','Café'],['🏃','Exercício'],['🧘','Bem-estar'],['🎨','Arte'],['🎵','Música'],['🎂','Aniversário'],['🐾','Pet'],['✈️','Viagem'],['🚗','Carro'],['🎯','Meta'],['💰','Dinheiro'],['🏦','Banco'],['💳','Cartão'],['💜','Roxo'],['🧡','Laranja'],['💙','Azul'],['💚','Verde'],['🛒','Compras'],['🍽️','Alimentação'],['🚌','Transporte'],['💡','Contas'],['🎁','Presente'],['📱','Celular']];
const colorOptions=[['#e9a8be','Rosa'],['#f2c75c','Amarelo'],['#a8c9ba','Menta'],['#b9a7da','Lavanda'],['#97c5e3','Azul'],['#efa58c','Pêssego'],['#d4b4db','Lilás'],['#ed9aa2','Coral'],['#c2cf97','Lima'],['#b5c8d7','Cinza azulado']];
function hslHex(h,s,l){s/=100;l/=100;const a=s*Math.min(l,1-l);return '#'+[0,8,4].map(n=>{const k=(n+h/30)%12,c=l-a*Math.max(-1,Math.min(k-3,9-k,1));return Math.round(255*c).toString(16).padStart(2,'0')}).join('')}
function hexHsl(hex){const a=hex.slice(1).match(/../g).map(n=>parseInt(n,16)/255),max=Math.max(...a),min=Math.min(...a),d=max-min,l=(max+min)/2;let h=0;if(d)h=max===a[0]?(a[1]-a[2])/d+(a[1]<a[2]?6:0):max===a[1]?(a[2]-a[0])/d+2:(a[0]-a[1])/d+4;return [h*60,d?d/(1-Math.abs(2*l-1))*100:0,l*100]}
function pickerField(input){const field=input.parentElement;if(field?.tagName==='LABEL'){const holder=document.createElement('div');holder.className='form-field';const title=document.createElement('span');title.textContent=field.firstChild?.textContent||'Selecionar';field.firstChild?.remove();holder.append(title,...Array.from(field.childNodes));field.replaceWith(holder)}}
function upgradePickers(root){
  root.querySelectorAll('input[name="emoji"],input[name="catemoji"]').forEach(input=>{
    input.type='hidden';const box=document.createElement('details');box.className='icon-picker picker';box.innerHTML=`<summary><span class="selected-emoji"></span><span>Escolher ícone</span><span class="picker-chevron">⌄</span></summary><div class="picker-panel"><div class="emoji-grid">${emojiOptions.map(([emoji,label])=>`<button type="button" data-emoji="${emoji}" aria-label="${label}" title="${label}">${emoji}</button>`).join('')}</div></div>`;input.after(box);const sync=()=>{box.querySelector('.selected-emoji').textContent=input.value;box.querySelectorAll('[data-emoji]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.emoji===input.value)))};box.querySelectorAll('[data-emoji]').forEach(b=>b.onclick=()=>{input.value=b.dataset.emoji;box.open=false;sync()});input.syncPicker=sync;sync();pickerField(input);
  });
  root.querySelectorAll('input[name="color"],input[name="catcolor"]').forEach(input=>{
    input.type='hidden';input.removeAttribute('style');const box=document.createElement('div');box.className='color-picker picker';box.innerHTML=`<div class="swatches" role="group" aria-label="Cores predefinidas">${colorOptions.map(([color,label])=>`<button type="button" data-color="${color}" style="--swatch:${color}" aria-label="${label}" title="${label}"></button>`).join('')}</div><details class="wheel-tab"><summary><span class="selected-color"></span>Personalizar · anel cromático</summary><div class="wheel-panel"><div class="color-wheel" role="img" aria-label="Anel cromático. Arraste para escolher matiz e saturação."><i class="wheel-marker"></i></div><div class="wheel-sliders"><label>Matiz<input class="hue" type="range" min="0" max="359" aria-label="Matiz"></label><label>Saturação<input class="saturation" type="range" min="0" max="100" aria-label="Saturação"></label><label>Luminosidade<input class="lightness" type="range" min="15" max="90" aria-label="Luminosidade"></label><output class="color-code"></output></div></div></details>`;input.after(box);let values=hexHsl(/^#[0-9a-f]{6}$/i.test(input.value)?input.value:'#e9a8be');const sync=()=>{values=hexHsl(input.value);box.querySelector('.selected-color').style.background=input.value;box.querySelector('.color-code').textContent=input.value.toUpperCase();box.querySelectorAll('[data-color]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.color===input.value)));['hue','saturation','lightness'].forEach((k,i)=>box.querySelector('.'+k).value=Math.round(values[i]));const theta=values[0]*Math.PI/180,r=values[1]*.45;box.querySelector('.wheel-marker').style.left=(50+Math.cos(theta)*r)+'%';box.querySelector('.wheel-marker').style.top=(50+Math.sin(theta)*r)+'%'};const update=()=>{input.value=hslHex(...values);sync()};box.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{input.value=b.dataset.color;sync()});['hue','saturation','lightness'].forEach((k,i)=>box.querySelector('.'+k).oninput=e=>{values[i]=Number(e.target.value);update()});const wheel=box.querySelector('.color-wheel'),point=e=>{const r=wheel.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2;values[0]=(Math.atan2(dy,dx)*180/Math.PI+360)%360;values[1]=Math.min(100,Math.hypot(dx,dy)/(r.width*.45)*100);update()};wheel.onpointerdown=e=>{wheel.setPointerCapture(e.pointerId);point(e)};wheel.onpointermove=e=>{if(wheel.hasPointerCapture(e.pointerId))point(e)};input.syncPicker=sync;sync();pickerField(input);
  });
}
function syncPickers(){document.querySelectorAll('input[type="hidden"]').forEach(input=>input.syncPicker?.())}
function ensureFinanceCategories(){if(!Array.isArray(db.financeCategories))db.financeCategories=[{id:'food',name:'Alimentação',emoji:'🍽️',color:'#efa58c'},{id:'transport',name:'Transporte',emoji:'🚌',color:'#97c5e3'},{id:'bills',name:'Contas',emoji:'💡',color:'#f2c75c'},{id:'shopping',name:'Compras',emoji:'🛒',color:'#e9a8be'},{id:'salary',name:'Renda',emoji:'💰',color:'#a8c9ba'}]}
let cashFilters={category:'',bank:'',type:''};
function financeCategory(id){return (db.financeCategories||[]).find(c=>c.id===id)}
function bindCashFilters(){for(const[id,key]of [['cashcategory','category'],['cashbank','bank'],['cashtype','type']]){const el=$('#'+id);if(el)el.onchange=e=>{cashFilters[key]=e.target.value;render()}}}
function deleteTask(id){const t=db.tasks.find(t=>t.id===id);if(!t)return;modal(`<h2>Excluir tarefa?</h2><p>Você quer excluir <strong>${esc(t.name)}</strong>?</p>${t.group?'<div class="notice">Ela será removida de todos os dias do intervalo.</div>':''}<div class="modal-actions"><button id="canceldelete">Cancelar</button><button id="confirmdelete" class="negative icon-action">${icon('trash')} Excluir tarefa</button></div>`);$('#canceldelete').onclick=()=>taskDetails(id);$('#confirmdelete').onclick=()=>{db.tasks=db.tasks.filter(t=>t.id!==id);save();close();render();toast('Tarefa excluída')}}
function transactionForm(type='in',id,project=''){
  ensureFinanceCategories();if(!db.banks.length){toast('Cadastre um banco para registrar movimentações.');bankForm();return}
  const t=id?db.transactions.find(x=>x.id===id):{type,name:'',bank:db.banks[0].id,amount:'',date:iso(today),note:'',project,category:''};
  modal(`<h2>${id?'Editar movimentação':t.type==='in'?'Nova entrada':'Nova saída'}</h2><form id="txform" class="form"><label>Tipo<select name="type"><option value="in" ${t.type==='in'?'selected':''}>Entrada</option><option value="out" ${t.type==='out'?'selected':''}>Saída</option></select></label><label>Nome<input name="name" required maxlength="100" value="${esc(t.name)}" placeholder="Ex.: Mercado, bolsa de estudos…"></label><div class="pair"><label>Valor (R$)<input name="amount" type="number" step="0.01" min="0.01" required value="${t.amount}"></label><label>Data<input name="date" type="date" required value="${t.date}"></label></div><label>Banco<select name="bank">${db.banks.map(b=>`<option value="${b.id}" ${b.id===t.bank?'selected':''}>${esc(b.emoji+' '+b.name)}</option>`).join('')}</select></label><label>Categoria<select name="category" id="txcategory"><option value="">Sem categoria</option>${db.financeCategories.map(c=>`<option value="${c.id}" ${c.id===t.category?'selected':''}>${esc(c.emoji+' '+c.name)}</option>`).join('')}<option value="new">＋ Criar categoria</option></select></label><div id="txnewcategory" class="form" hidden><label>Nome da categoria<input name="catname" maxlength="50"></label><div class="pair"><label>Ícone<input name="catemoji" value="🛒"></label><label>Cor<input name="catcolor" type="color" value="#e9a8be"></label></div></div><label>Associar a um plano · opcional<select name="project"><option value="">Sem plano</option>${db.projects.map(p=>`<option value="${p.id}" ${p.id===t.project?'selected':''}>${esc(p.emoji+' '+p.name)}</option>`).join('')}</select></label><label>Observação · opcional<textarea name="note">${esc(t.note)}</textarea></label><div class="modal-actions">${id?`<button type="button" id="deletetx" class="negative icon-action">${icon('trash')} Excluir</button>`:''}<button type="button" id="canceltx">Cancelar</button><button class="primary">Salvar movimentação</button></div></form>`);
  $('#txcategory').value=t.category||'';$('#txnewcategory').style.display='none';$('#txcategory').onchange=e=>{const show=e.target.value==='new';$('#txnewcategory').hidden=!show;$('#txnewcategory').style.display=show?'grid':'none';$('#txform [name="catname"]').required=show};$('#canceltx').onclick=close;
  if(id)$('#deletetx').onclick=()=>{if(confirm('Excluir transação e recalcular os saldos?')){db.transactions=db.transactions.filter(x=>x.id!==id);save();close();render()}};
  $('#txform').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),amount=Math.round(Number(f.amount)*100)/100;if(!f.name.trim()||!Number.isFinite(amount)||amount<=0)return;let cid=f.category;if(cid==='new'){if(!f.catname.trim()){toast('Informe o nome da categoria.');return}const c={id:uid(),name:f.catname.trim(),emoji:f.catemoji,color:f.catcolor};db.financeCategories.push(c);cid=c.id}const record={id:id||uid(),type:f.type,name:f.name.trim(),amount,bank:f.bank,date:f.date,project:f.project,note:f.note,category:cid};if(id)db.transactions[db.transactions.findIndex(x=>x.id===id)]=record;else db.transactions.push(record);save();close();render();toast('Movimentação salva')};
}
function financeCategoryForm(id){ensureFinanceCategories();const c=id?financeCategory(id):{name:'',emoji:'🛒',color:'#e9a8be'};modal(`<h2>${id?'Editar':'Nova'} categoria do caixa</h2><form id="financecategoryform" class="form"><label>Nome<input name="name" required maxlength="50" value="${esc(c.name)}"></label><div class="pair"><label>Ícone<input name="emoji" value="${esc(c.emoji)}"></label><label>Cor<input name="color" type="color" value="${c.color}"></label></div><div class="modal-actions"><button class="primary">Salvar categoria</button></div></form>`);$('#financecategoryform').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(!f.name.trim())return;const record={id:id||uid(),name:f.name.trim(),emoji:f.emoji,color:f.color};if(id)db.financeCategories[db.financeCategories.findIndex(c=>c.id===id)]=record;else db.financeCategories.push(record);save();close();render()}}
async function prepareOCRPhoto(file){
  const bitmap=await createImageBitmap(file),scale=Math.min(1,2200/Math.max(bitmap.width,bitmap.height)),source=document.createElement('canvas');source.width=Math.round(bitmap.width*scale);source.height=Math.round(bitmap.height*scale);const ctx=source.getContext('2d',{willReadFrequently:true});ctx.drawImage(bitmap,0,0,source.width,source.height);bitmap.close();
  const pixels=ctx.getImageData(0,0,source.width,source.height),geometry=ScalePhoto.preparePixels(pixels.data,source.width,source.height),canvas=document.createElement('canvas');canvas.width=geometry.width;canvas.height=geometry.height;const out=canvas.getContext('2d');const image=out.createImageData(geometry.width,geometry.height);image.data.set(geometry.rgba);
  if(!geometry.rectified)for(let i=0;i<image.data.length;i+=4){const gray=image.data[i]*.299+image.data[i+1]*.587+image.data[i+2]*.114,v=Math.max(0,Math.min(255,(gray-128)*1.35+150));image.data[i]=image.data[i+1]=image.data[i+2]=v}
  out.putImageData(image,0,0);return {canvas,geometry};
}
async function readScale(){
  if(!importFile){toast('Escolha uma foto da escala.');return}if(!$('#scalemonth').value){toast('Escolha o mês da escala.');return}if(importReading)return;
  importReading=true;const month=$('#scalemonth').value,name=$('#scalename').value.trim()||'Isabela',status=$('#ocrstatus');$('#readscale').disabled=true;let worker;
  try{
    status.textContent='Preparando a foto e carregando o leitor…';
    if(!window.Tesseract)await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js';script.onload=resolve;script.onerror=reject;document.head.appendChild(script)});
    worker=await Tesseract.createWorker('por',1,{logger:m=>{if(status.isConnected&&m.status==='recognizing text')status.textContent=`Lendo as colunas… ${Math.round(m.progress*100)}%`}});
    await worker.setParameters({tessedit_pageseg_mode:'11',preserve_interword_spaces:'1'});
    const photo=await prepareOCRPhoto(importFile);let parsed;
    if(photo.geometry.rectified){parsed=await ScaleOCR.readCells(worker,photo.canvas,photo.geometry,name,(done,total)=>{if(status.isConnected)status.textContent=`Lendo célula ${done+1} de ${total}…`})}
    else {let result=await worker.recognize(photo.canvas);parsed=ScaleOCR.parseScale(result.data,name);if(!parsed.complete){await worker.setParameters({tessedit_pageseg_mode:'3'});const retry=await worker.recognize(photo.canvas),candidate=ScaleOCR.parseScale(retry.data,name);if(candidate.complete||candidate.assigned>parsed.assigned)parsed=candidate}}
    if(!status.isConnected||!$('#modal').open)return;
    importReview(parsed.rows,month,parsed.complete?'Leitura automática · confira todos os campos':'Leitura parcial · '+parsed.notes.join(' '),parsed.text,name);
  }catch(err){console.error('OCR:',err);if(status.isConnected)status.textContent='O leitor não conseguiu processar a foto. Isso pode ser uma falha no carregamento, não na imagem. Você pode tentar novamente ou usar a revisão manual.'}
  finally{try{if(worker)await worker.terminate()}finally{importReading=false;const b=$('#readscale');if(b)b.disabled=false}}
}

